import{_ as e,c as s,o as t,b0 as i}from"./chunks/framework.BWMBvyU7.js";const n="/programming-docs/assets/image-20220618110846035.CrPd14uu.png",l="/programming-docs/assets/image-20220618111433972.YA91w00n.png",r="/programming-docs/assets/image-20220618111453975.Bzq7fFo_.png",d="/programming-docs/assets/image-20220618111522630.DofqTQoq.png",o="/programming-docs/assets/image-20220623061241634.CqpQDm1b.png",p="/programming-docs/assets/image-20220623061406002.DHdjnlKL.png",c="/programming-docs/assets/image-20220623063051820.CXoHbFWc.png",h="/programming-docs/assets/image-20220623063242825.DNCMZBku.png",g="/programming-docs/assets/image-20220623063559863.ivSdkUva.png",m="/programming-docs/assets/image-20220623064059307.BX1qJtHv.png",u="/programming-docs/assets/image-20220623065749049.C0Dt2wg6.png",b="/programming-docs/assets/image-20220623070731215.BD8D2Wal.png",k="/programming-docs/assets/image-20220623071226766.BettCt2h.png",_="/programming-docs/assets/image-20220623071228755.CWXtZqrv.png",v="/programming-docs/assets/image-20220623082957437.DspSXZ9s.png",w="/programming-docs/assets/image-20220623085909290.De5eXYxV.png",E=JSON.parse('{"title":"LV020-wireshark","description":null,"frontmatter":{"title":"LV020-wireshark","date":"2026-03-16T14:16:24.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/net/net-tools/126d38f258381c0c5adbb0e7","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-03-16T14:16:24.448Z","fulluuid":"c5adbb0e79304ae3a065c586b2a7ebc7","useduuid":"c5adbb0e7"}},"headers":[],"relativePath":"sdoc/net/net-tools/126d38f258381c0c5adbb0e7.md","filePath":"sdoc/04-网络相关/01-网络工具/LV020-wireshark.md","lastUpdated":1773672539000}'),y={name:"sdoc/net/net-tools/126d38f258381c0c5adbb0e7.md"};function F(f,a,x,C,P,q){return t(),s("div",null,[...a[0]||(a[0]=[i('<h1 id="lv020-wireshark" tabindex="-1">LV020-wireshark <a class="header-anchor" href="#lv020-wireshark" aria-label="Permalink to &quot;LV020-wireshark&quot;">​</a></h1><p>本文主要是网络基础——wireshark工具介绍和使用的相关笔记，若笔记中有错误或者不合适的地方，欢迎批评指正😃。</p><h2 id="一、wireshark简介" tabindex="-1">一、<code>wireshark</code>简介 <a class="header-anchor" href="#一、wireshark简介" aria-label="Permalink to &quot;一、`wireshark`简介&quot;">​</a></h2><p><code>WireShark</code>是非常流行的网络封包分析工具，可以截取各种网络数据包，并显示数据包详细信息。常用于开发测试过程中各种问题定位。<code>Wireshark</code> 于 <code>1998</code> 年首次发布，最初被称为 <code>Ethereal</code> 。<code>2006</code> 年，由于商标问题，开发商不得不将其名称改为 <code>Wireshark</code> 。另外该软件可以运行在 <code>Windows</code> 和 <code>Linux</code> 操作系统上。</p><h2 id="二、wireshark安装" tabindex="-1">二、<code>wireshark</code>安装 <a class="header-anchor" href="#二、wireshark安装" aria-label="Permalink to &quot;二、`wireshark`安装&quot;">​</a></h2><h3 id="_1-在ubuntu中安装" tabindex="-1">1. 在<code>Ubuntu</code>中安装 <a class="header-anchor" href="#_1-在ubuntu中安装" aria-label="Permalink to &quot;1. 在`Ubuntu`中安装&quot;">​</a></h3><p>为了获取最新版本的<code>wireshark</code>，我们通过<code>PPA</code>来安装这个软件：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add-apt-repository</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ppa:wireshark-dev/stable</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wireshark</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>主要是上边的三条命令，按照提示进行安装即可。通过这种方式进行安装，即使安装了旧版本的 <code>Wireshark</code> ，它也将更新为新版本。</p><p>安装时（安装过程可能比较慢长，可以做点其他的事），系统将会询问我们是否允许非超级用户捕获数据包。选择<code>Yes</code>允许的话，即便不是<code>root</code>用户，也可以使用软件捕获数据包，选择<code>No</code>将会限制非超级用户捕获数据包，选择完毕后便会完成安装。</p><img src="'+n+'" alt="image-20220618110846035" style="zoom:50%;"><p>安装完成后，打开软件，软件界面如下图所示：</p><img src="'+l+'" alt="image-20220618111433972" style="zoom:50%;"><p>操作完成后，最好重启一下，这样就可以识别到当前系统的网卡啦，我安装好的时候是没显示<code>ens</code>开头的信息的，重启一下<code>Ubuntu</code>系统就好啦。</p><p>如果说在软件包设置那个界面选了 否(<code>No</code>) ，这个时候当我们终端直接运行<code>wiresirk</code>是没有问题的，可以正常打开界面，但是当我们开始抓包的时候就会弹出以下提醒，要是想在非<code>root</code>用户下也可以捕获数据包，要怎么办呢？</p><img src="'+r+'" alt="image-20220618111453975" style="zoom:50%;"><p>我们在终端输入以下命令，便会重新弹出软件包设置界面。然后选择是即可。</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dpkg-reconfigure</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wireshark-common</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>软件设置完毕后，由于我们需要允许非超级用户捕获数据包，因此必须将该用户添加到 <code>wireshark</code> 组。使用 <code>usermod</code>命令将自己添加到 <code>wireshark</code> 组。</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usermod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -aG</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wireshark</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">whoami</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>如此便可以在非<code>root</code>下，正常捕获数据包啦。</p><h3 id="_2-在windows下安装" tabindex="-1">2. 在<code>Windows</code>下安装 <a class="header-anchor" href="#_2-在windows下安装" aria-label="Permalink to &quot;2. 在`Windows`下安装&quot;">​</a></h3><p>其实多数情况，我们可能会在虚拟机中的<code>wireshark</code>中捕获数据包，然后放到<code>Windows</code>下来分析，可能会更方便一些。我们可以在这里下载<code>wireshark</code>软件的安装包：<a href="https://www.wireshark.org/#download" target="_blank" rel="noreferrer">Wireshark · Go Deep-Download. </a></p><div class="language-html vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">https://www.wireshark.org/#download</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>我们在这里下载<code>Windows Installer (64-bit)</code>，下载完成后，双击<code>.exe</code>可执行文件即可开始安装，这个没什么好说的，就是一路默认，一路<code>next</code>就完事了。安装完成后，双击运行，界面如下所指示：</p><img src="'+d+'" alt="image-20220618111522630" style="zoom:33%;"><h2 id="三、基本使用" tabindex="-1">三、基本使用 <a class="header-anchor" href="#三、基本使用" aria-label="Permalink to &quot;三、基本使用&quot;">​</a></h2><h3 id="_1-抓包实例" tabindex="-1">1. 抓包实例 <a class="header-anchor" href="#_1-抓包实例" aria-label="Permalink to &quot;1. 抓包实例&quot;">​</a></h3><p>首先还是需要来看一下怎么抓包，这里我们抓取一下<code>ping</code>命令操作过程中的数据包，这里我们直接在<code>Windows</code>下的<code>wireshark</code>软件中进行。</p><h4 id="_1-1-选择网卡" tabindex="-1">1.1 选择网卡 <a class="header-anchor" href="#_1-1-选择网卡" aria-label="Permalink to &quot;1.1 选择网卡&quot;">​</a></h4><p>当我们进入<code>wireshark</code>的时候，会看到接口选择界面，我们选择显示所有接口，由于我的电脑连接的是<code>Wifi</code>所以我这里选择<code>WLAN</code>。</p><img src="'+o+'" alt="image-20220623061241634" style="zoom:33%;"><p>双击之后，便会进入抓包的界面（或者就是【右键】→【<code>start capture</code>】），如下图所示：</p><img src="'+p+'" alt="image-20220623061406002" style="zoom:33%;"><p>双击之后直接就开始抓包了，这个时候我还开着网页以及一些联网的应用，所以出来直接就有很多数据了，在<code>Ubuntu</code>中的时候好像就没有这么多的。</p><h4 id="_1-2-ping" tabindex="-1">1.2 <code>ping</code> <a class="header-anchor" href="#_1-2-ping" aria-label="Permalink to &quot;1.2 `ping`&quot;">​</a></h4><p>保持开启抓包的状态，然后我们打开<code>Windows</code>中的命令提示符，输入以下命令：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ping</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> www.baidu.com</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>然后就会测试我们能否与该网站连通，界面如下所示：</p><img src="'+c+'" alt="image-20220623063051820" style="zoom:50%;"><h4 id="_1-3-停止抓包" tabindex="-1">1.3 停止抓包 <a class="header-anchor" href="#_1-3-停止抓包" aria-label="Permalink to &quot;1.3 停止抓包&quot;">​</a></h4><p>如下图所示，点击这个红色的方框就可以停止抓包了。</p><img src="'+h+'" alt="image-20220623063242825" style="zoom:33%;"><h4 id="_1-4-保存数据" tabindex="-1">1.4 保存数据 <a class="header-anchor" href="#_1-4-保存数据" aria-label="Permalink to &quot;1.4 保存数据&quot;">​</a></h4><p>我们通过该软件抓到的数据包是可以进行保存，并在其他计算机中使用该软件打开分析的。</p><img src="'+g+'" alt="image-20220623063559863" style="zoom:33%;"><p>然后我们这一次抓的包就会保存下来，保存的数据包文件后缀名为<code>.pcapn</code>。</p><h3 id="_2-界面简介" tabindex="-1">2. 界面简介 <a class="header-anchor" href="#_2-界面简介" aria-label="Permalink to &quot;2. 界面简介&quot;">​</a></h3><p>界面如下图所示：</p><img src="'+m+'" alt="image-20220623064059307" style="zoom:33%;"><ul><li>（1）菜单栏：用于调试，配置，保存等功能，其实所有的功能都可以在菜单栏进行操作；</li><li>（2）工具栏：就是一些常用功能的快捷方式，如保存捕获数据、停止捕获和开始捕获等；</li><li>（3）过滤栏：在这里指定过滤的规则，过滤我们需要的数据包；</li><li>（4）数据包列表：这里是我们捕获的所有数据包，每一行就是一个数据包；</li><li>（5）数据包详情：每个数据包的详细数据；有的数据包详情中可能不仅仅有上图的四条：</li></ul><img src="'+u+'" alt="image-20220623065749049" style="zoom:33%;"><table tabindex="0"><thead><tr><th style="text-align:left;">数据包内容</th><th>说明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>Frame</code></td><td>物理层的数据帧概况，对应的是物理层</td></tr><tr><td style="text-align:left;"><code>Ethernet II</code></td><td>数据链路层以太网帧头部信息，对应的是数据链路层</td></tr><tr><td style="text-align:left;"><code>Internet Protocol Version 4</code></td><td>互联网层<code>IP</code>包的头部信息，对应的是网络层</td></tr><tr><td style="text-align:left;"><code>Transmission Control Protocol</code></td><td>传输层的数据段头部信息，此处是<code>TCP</code>，对应的是传输层</td></tr><tr><td style="text-align:left;"><code>Hypertext Transfer Protocol</code></td><td>应用层的信息，这一种就是<code>HTTP</code>协议，对应的是应用层</td></tr></tbody></table><p>与<code>OSI</code>七层模型的对应关系如下图所示：</p><img src="'+b+'" alt="image-20220623070731215" style="zoom:33%;"><ul><li>（6）数据包字节：数据包对应的字节流，二进制的形式显示。</li></ul><h3 id="_3-过滤器" tabindex="-1">3. 过滤器 <a class="header-anchor" href="#_3-过滤器" aria-label="Permalink to &quot;3. 过滤器&quot;">​</a></h3><p>我们在抓取数据包的时候会抓取大量不相关的数据包，如何过滤出我们需要的呢？<code>wireshark</code>给我们提供了提供了两个过滤器：捕获过滤器 和 显示过滤器。两个过滤器的过滤思路不同。</p><ul><li>捕获过滤器：重点在动作，需要的数据包才抓，不需要的就不抓。</li><li>显示过滤器：重点在数据包的显示，所有的数据包已经抓了，只是不显示不需要的。</li></ul><h4 id="_3-1-捕获过滤器" tabindex="-1">3.1 捕获过滤器 <a class="header-anchor" href="#_3-1-捕获过滤器" aria-label="Permalink to &quot;3.1 捕获过滤器&quot;">​</a></h4><h5 id="_3-1-1-设置方式" tabindex="-1">3.1.1 设置方式 <a class="header-anchor" href="#_3-1-1-设置方式" aria-label="Permalink to &quot;3.1.1 设置方式&quot;">​</a></h5><p>我们只想抓一些自己需要的包，那么我们就需要在启动抓包之前或者停止抓包后使用捕获过滤器，我们在抓包开始之前，打开捕获过滤器界面：【菜单栏】→【捕获】→【选项】，然后便会打开以面板：</p><img src="'+k+'" alt="image-20220623071226766" style="zoom:33%;"><p>【注意】这里会有自动的语法检测，当输入框变为绿色的时候说明语法正确，可以开始捕获，若为粉红色，则不能开始捕获，开始按钮也为灰色，无法选中。</p><p>有一些通用的捕获过滤器表达式每一次都全部写一遍不免有些麻烦，我们可以在捕获过滤器选项中保存一些通用的过滤器，然后在设置捕获过滤器的时候直接选择即可：【菜单栏】→【捕获】→【捕获过滤器】</p><img src="'+_+'" alt="image-20220623071228755" style="zoom:33%;"><h5 id="_3-1-2-表达式语法" tabindex="-1">3.1.2 表达式语法 <a class="header-anchor" href="#_3-1-2-表达式语法" aria-label="Permalink to &quot;3.1.2 表达式语法&quot;">​</a></h5><p>捕获过滤器表达式的语法格式被称为<code>BPF</code>，（全称 <code>Berkeley Packet Filter</code>），中文叫伯克利封包过滤器。语法格式为：</p><div class="language-BPF vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">BPF</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;Protocol&gt; &lt;Direction&gt; &lt;Type&gt; &lt;Value&gt; &lt;逻辑运算符&gt; &lt;其他表达式&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>各部分含义如下：</p><table><tbody><tr><td align="center" width="150px">协议 Protocol</td><td align="left">各种网络协议，比如：tcp、udp、http</td></tr><tr><td align="center" width="150px">方向 Direction</td><td align="left">源地址（src）、目标地址（dst）</td></tr><tr><td align="center" width="150px">类型 Type</td><td align="left">主机（host）、网段（net）、端口（port）</td></tr><tr><td align="center" width="150px">值 value</td><td align="left">主机（host）、网段（net）、端口（port）等的值</td></tr><tr><td align="center" width="150px">逻辑运算符</td><td align="left">与（ &amp;&amp; ）、或（ || ）、非（ ！）</td></tr><tr><td align="center" width="150px">其他表达式</td><td align="left">需要同时应用的其他过滤器表达式</td></tr></tbody></table> 这些个元素可以自由组合。下面是一些实例： <ul><li>抓取<code>TCP</code>数据包</li></ul><p>我们新增一个捕获过滤器，表达式的值设为：</p><div class="language-BPF vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">BPF</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TCP</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><img src="'+v+'" alt="image-20220623082957437" style="zoom:33%;"><p>然后我们就可以开始只捕捉<code>TCP</code>的数据包了。</p><ul><li>抓取固定源的数据包</li></ul><div class="language-BPF vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">BPF</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src host 192.168.1.10</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这个就不再放图了，跟上边一样的设置方法。</p><h4 id="_3-3-显示过滤器" tabindex="-1">3.3 显示过滤器 <a class="header-anchor" href="#_3-3-显示过滤器" aria-label="Permalink to &quot;3.3 显示过滤器&quot;">​</a></h4><h5 id="_3-3-1-设置方式" tabindex="-1">3.3.1 设置方式 <a class="header-anchor" href="#_3-3-1-设置方式" aria-label="Permalink to &quot;3.3.1 设置方式&quot;">​</a></h5><p>下边我们来看一下另一种显示过滤器，这种过滤器会抓取全部的包，然后通过显示过滤器显示我们需要的包。显示过滤器的使用就在工具栏下边，即便是正在捕获数据包，也依然可以使用显示过滤器：</p><p><img src="'+w+`" alt="image-20220623085909290"></p><p>【注意】这里也会有自动的语法检测，当输入框变为绿色的时候说明语法正确，若为粉红色，说明语法有误，需要修改。</p><h5 id="_3-3-2-表达式语法" tabindex="-1">3.3.2 表达式语法 <a class="header-anchor" href="#_3-3-2-表达式语法" aria-label="Permalink to &quot;3.3.2 表达式语法&quot;">​</a></h5><p>显示过滤器的语法如下：</p><div class="language-BPF vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">BPF</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;协议&gt;.&lt;字段&gt; &lt;比较运算符&gt; &lt;值&gt; &lt;逻辑运算符&gt; &lt;其他表达式&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>各部分说明如下：</p><table><tbody><tr><td align="left" width="150px">协议</td><td align="left">tcp、udp、http等</td></tr><tr><td align="left" width="150px">字段</td><td align="left">源IP端口(srcport)、目标IP端口(dstport)等</td></tr><tr><td align="left" width="150px">比较运算符 </td><td align="left">&gt;、&lt;、==、&gt;=、&lt;=、!=</td></tr><tr><td align="left" width="150px">逻辑运算符 </td><td align="left">and、or、not、xor(有且仅有一个条件被满足)</td></tr></tbody></table> 例如， <div class="language-BPF vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">BPF</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tcp.srcport == 443     # 只抓取源IP端口为443的tcp数据</span></span>
<span class="line"><span>tcp.dstport == 8181    # 只抓取目标IP端口为8181的tcp数据</span></span>
<span class="line"><span>not arp                # 不是arp的其他数据</span></span>
<span class="line"><span>tcp                    # 显示TCP协议的包</span></span>
<span class="line"><span>tcp.srcport==443       # 显示TCP协议源端口为443的包</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ip.src == 192.168.1.100 and tcp.dstport == 80</span></span>
<span class="line"><span>ip.addr == 192.168.1.100 and udp.port == 3000</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div>`,92)])])}const T=e(y,[["render",F]]);export{E as __pageData,T as default};
